// Case-study data for /work/<slug>. Plain JSON-safe values only (it is passed from server to client
// components). Facts come from the real files (case-media.json, generated by
// scripts/media/build-case-media.mjs) and research/content/films-audit.md (case-shots.json).
// Everything an editor has to write is a placeholder until the client sends copy: // CONFIRM.
// Hard rules: no agency or developer names in the copy; never name the NASCAR actor or any livery sponsor;
// no invented clients, years, numbers or awards.
import shotsJson from "./case-shots.json";
import mediaJson from "./case-media.json";
import { MEDIA, PROJECTS, type Project } from "./projects";

// ---------- types ----------
export type ShotTag = "car" | "set" | "light" | "fx" | "camera";

export type Shot = {
  n: number; // 1-based, also the frame number (frames/NN)
  in: number; // seconds into the full film
  out: number;
  at: number; // time of the frame grab
  title: string;
  built: string; // one line on what is on screen / what was built // CONFIRM WITH ADIL
  tags: ShotTag[];
  w: number; // frame size (1600 version)
  h: number;
};

export type CaseFilm = {
  src: string; // full film with sound (H.264 + AAC, faststart)
  duration: number; // seconds
  runtime: string; // "0:32"
  width: number;
  height: number;
  bytes: number;
};

export type CaseStill = {
  n: number; // 1-based (stills/NN-*)
  w: number; // 1600 version
  h: number;
  w3200: number; // loupe version
  h3200: number;
  masterW: number; // the client's master
  masterH: number;
  caption: string; // CONFIRM WITH ADIL
  alt: string;
};

export type SpecField = { label: string; value: string; confirm?: boolean };
export type CreditGroup = { group: string; items: { role: string; name: string; confirm?: boolean }[] };

/** Body sections a template can lay out, in the order given by layout.order. */
export type BodySection =
  | "shots" // film: "In this shot", pinned frame + shot cards
  | "frames" // film: frames rhythm (layout.framesPreset)
  | "stills" // film with stills (McLaren): a stills block
  | "strip" // stills: light-box drag strip
  | "loupe" // stills: hold to inspect
  | "grid"; // stills: 1/2/1 grid with captions

export type CaseLayout = {
  /** Film frames rhythm: "full" (full-bleed run), "two-up" (pairs), "offset" (one image + paragraph, staggered). */
  framesPreset: "full" | "two-up" | "offset";
  /** Side of the pinned frame in "In this shot". */
  shotsSide: "left" | "right";
  /** Films: "split" = the viewer holds ~58% of the width beside the shot cards; "stage" = the viewer fills
   *  the screen and the cards roll over it on the other side (desktop; phones and reduced motion use split). */
  viewer?: "split" | "stage";
  /** Where the key colour shows (sparingly): rules, shot numbers/timecodes, or the chevrons. */
  accent: "rule" | "numbers" | "chevron";
  /** Body background. */
  surface: "ink" | "ink-2";
  /** Body sections, top to bottom. */
  order: BodySection[];
  /** Stills: the stills that strobe in on the hero; the last one is the key still. */
  strobe?: number[];
  /** Stills: the still used for "hold to inspect", and where the loupe starts (0..1). */
  loupe?: number;
  loupeAt?: [number, number];
};

export type CaseData = {
  slug: string;
  title: string;
  kind: string;
  type: Project["type"];
  blurb: string;
  aspect: number;
  index: number; // 0-based position in PROJECTS
  total: number;
  /** Dominant vivid colour of the poster (hex), its plain average, and a version lifted to read on ink. */
  key: string;
  keyAvg: string;
  keyUi: string;
  intro: { lead: string; body: string; draft: boolean }; // CONFIRM WITH ADIL
  spec: SpecField[]; // CONFIRM WITH ADIL (the "To confirm" values)
  format: string; // "16:9 · 3840×2160 master · 24 fps"
  film: CaseFilm | null;
  shots: Shot[]; // films only
  stills: CaseStill[]; // stills projects and McLaren
  credits: CreditGroup[]; // CONFIRM WITH ADIL
  layout: CaseLayout;
  prev: string;
  next: string;
  /** Tiny blurred stand-ins (data URIs) for this page's pictures, keyed "frames/01", "rhythm/01",
   *  "stills/01", "poster". Added on the server by components/case/shared/lqip.ts (CaseShell), so only the
   *  page's own entries travel to the browser. Absent = no stand-in (the box keeps its dark fill). */
  lqip?: Record<string, string>;
};

// ---------- generated media facts ----------
type MediaMeta = {
  films: Record<string, { duration: number; runtime: string; width: number; height: number; bytes: number; frames: { n: number; at: number; w: number; h: number }[] }>;
  stills: Record<string, { n: number; w: number; h: number; w3200: number; h3200: number; masterW: number; masterH: number }[]>;
  keys: Record<string, { key: string; avg: string; ui: string }>;
};
const META = mediaJson as unknown as MediaMeta;
type ShotSrc = { in: number; out: number; at?: number; title: string; built: string; tags: string[] };
const SHOTS = shotsJson as unknown as Record<string, ShotSrc[]>;

