// ---------- helpers (safe on server and client) ----------
const pad2 = (n: number) => String(n).padStart(2, "0");

export const aspectName = (a: number) =>
  Math.abs(a - 16 / 9) < 0.01 ? "16:9" : Math.abs(a - 5 / 2) < 0.01 ? "5:2" : Math.abs(a - 8 / 5) < 0.01 ? "8:5" : `${a.toFixed(2)}:1`;

/** 75.4 -> "1:15". */
export const mmss = (s: number) => `${Math.floor(s / 60)}:${pad2(Math.floor(s % 60))}`;

/** Film timecode at 24 fps: 75.4 -> "01:15:10" (mm:ss:ff). */
export const timecode = (s: number, fps = 24) => {
  const f = Math.floor(s * fps + 1e-6);
  return `${pad2(Math.floor(f / fps / 60))}:${pad2(Math.floor(f / fps) % 60)}:${pad2(f % fps)}`;
};

/** One shot frame (frames/NN, 800 or 1600 wide). */
export const frameSrc = (slug: string, n: number, w: 800 | 1600 = 1600, fmt: "avif" | "webp" = "webp") =>
  `${MEDIA}/work/${slug}/frames/${pad2(n)}${w === 800 ? "-800" : ""}.${fmt}`;

/** srcSet strings for <picture>: <source type="image/avif" srcSet={s.avif} sizes=...> + <img srcSet={s.webp}>. */
export const frameSet = (slug: string, n: number) => ({
  avif: `${frameSrc(slug, n, 800, "avif")} 800w, ${frameSrc(slug, n, 1600, "avif")} 1600w`,
  webp: `${frameSrc(slug, n, 800, "webp")} 800w, ${frameSrc(slug, n, 1600, "webp")} 1600w`,
  src: frameSrc(slug, n, 1600, "webp"),
});

/** One still at 800, 1600 or 3200 (loupe) wide. */
export const stillSrc = (slug: string, n: number, w: 800 | 1600 | 3200 = 1600, fmt: "avif" | "webp" = "webp") =>
  `${MEDIA}/work/${slug}/stills/${pad2(n)}-${w}.${fmt}`;

/** srcSet strings for a still (800/1600; the 3200 loupe tile is loaded on demand with stillSrc). */
export const stillSet = (slug: string, n: number) => ({
  avif: `${stillSrc(slug, n, 800, "avif")} 800w, ${stillSrc(slug, n, 1600, "avif")} 1600w`,
  webp: `${stillSrc(slug, n, 800, "webp")} 800w, ${stillSrc(slug, n, 1600, "webp")} 1600w`,
  src: stillSrc(slug, n, 1600, "webp"),
});

export const filmSrc = (slug: string) => `${MEDIA}/work/${slug}/film.mp4`;

/** The blurred stand-in for one of the page's pictures ("frames/03", "stills/01", "poster"), if any. */
export const lqipOf = (d: Pick<CaseData, "lqip">, kind: "frames" | "rhythm" | "stills" | "poster", n?: number) =>
  d.lqip?.[kind === "poster" ? "poster" : `${kind}/${pad2(n ?? 1)}`];

// ---------- build ----------
function build(p: Project, index: number): CaseData {
  const m = META.films[p.slug];
  const k = META.keys[p.slug] ?? { key: "#8a8a90", avg: "#3a3a40", ui: "#b9b9c0" };
  const film: CaseFilm | null =
    p.type === "film" && m
      ? { src: filmSrc(p.slug), duration: m.duration, runtime: m.runtime, width: m.width, height: m.height, bytes: m.bytes }
      : null;
  const shots: Shot[] = (SHOTS[p.slug] ?? []).map((s, i) => {
    const f = m?.frames[i];
    return {
      n: i + 1,
      in: s.in,
      out: s.out,
      at: f?.at ?? s.at ?? +((s.in + s.out) / 2).toFixed(2),
      title: s.title,
      built: s.built,
      tags: s.tags as ShotTag[],
      w: f?.w ?? 1600,
      h: f?.h ?? Math.round(1600 / p.aspect),
    };
  });
  const text = STILL_TEXT[p.slug] ?? [];
  const stills: CaseStill[] = (META.stills[p.slug] ?? []).map((s, i) => ({
    ...s,
    caption: text[i]?.[0] ?? `Still ${pad2(s.n)}.`,
    alt: text[i]?.[1] ?? `${p.title}, still ${s.n}.`,
  }));

  // Formats from the real files: films are 3840 wide masters at 24 fps; stills are ~8K masters.
  const format =
    p.type === "film"
      ? `${aspectName(p.aspect)} · ${p.aspect > 2 ? "3840×1536" : "3840×2160"} master · 24 fps`
      : `${stills.length} stills · ${stills.every((s) => Math.abs(s.masterW / s.masterH - 16 / 9) < 0.02) ? "16:9" : "mixed ratios"} · 8K masters`;

  const spec: SpecField[] = [
    { label: "Client", value: TBC, confirm: true },
    { label: "Brand", value: BRAND[p.slug] ?? TBC, confirm: !BRAND[p.slug] },
    { label: "Year", value: TBC, confirm: true },
    { label: "Our role", value: TBC, confirm: true },
    { label: "Services", value: TBC, confirm: true },
    { label: "Format", value: format },
    film ? { label: "Runtime", value: film.runtime } : { label: "Stills", value: pad2(stills.length) },
  ];

  const n = PROJECTS.length;
  return {
    slug: p.slug,
    title: p.title,
    kind: p.kind,
    type: p.type,
    blurb: p.blurb,
    aspect: p.aspect,
    index,
    total: n,
    key: k.key,
    keyAvg: k.avg,
    keyUi: k.ui,
    intro: { ...(INTRO[p.slug] ?? { lead: p.blurb, body: "" }), draft: true },
    spec,
    format,
    film,
    shots: p.type === "film" ? shots : [],
    stills,
    credits: p.type === "film" ? FILM_CREDITS : STILLS_CREDITS,
    layout: LAYOUT[p.slug] ?? LAYOUT["audi-rs5-estate"],
    prev: PROJECTS[(index - 1 + n) % n].slug,
    next: PROJECTS[(index + 1) % n].slug,
  };
}

export const CASES: CaseData[] = PROJECTS.map(build);

export const getCase = (slug: string) => CASES.find((c) => c.slug === slug) ?? null;
